      draft,
      attachments,
      editorHtml,
      mode,
      aspectRatio,
      imageResolution,
      imageQuality,
      resolution,
      videoModel,
      durationSeconds,
      audioEnabled,
      selectedStylePresetId,
      scriptType,
      referenceIntent,
      audioType,
      selectedVoice,
      sfxLoop,
      sfxDurationAuto,
      sfxDurationSeconds,
      sfxPromptInfluence,
      musicDurationSeconds,
      musicDurationAuto,
      musicInstrumental,
      musicLyricsMode,
      musicCustomLyrics,
      musicVariants,
      musicModelId,
      musicFinetuneId,
      musicWorkflow,
      musicStoreForInpainting,
      musicSourceSongId,
      previous: composerContextsRef.current[key],
